import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { createRequire } from 'node:module';
import { pathToFileURL } from 'node:url';

const nmDir = process.env.KALFA_UI_NODE_MODULES;
if (!nmDir || !fs.existsSync(nmDir)) {
  throw new Error('Svelte/JSDOM test paketleri (KALFA_UI_NODE_MODULES) bulunamadı; gerçek Svelte derleme ve DOM render olmadan K03 geçemez');
}

const bilesenYolu = path.resolve(import.meta.dirname, '../src/SayacPaneli.svelte');
const ham = fs.readFileSync(bilesenYolu, 'utf8');
const yorumsuzHtml = ham.replace(/<!--[\s\S]*?-->/g, '');
if (/\bstyle\s*=/.test(yorumsuzHtml)) {
  throw new Error('CSP ihlali: sabit style özniteliği kullanılamaz');
}

const req = createRequire(import.meta.url);
const ts = req(path.join(nmDir, 'typescript/lib/typescript.js'));
const svelteCompiler = await import(pathToFileURL(path.join(nmDir, 'svelte/src/compiler/index.js')).href);
const svelteClient = await import(pathToFileURL(path.join(nmDir, 'svelte/src/index-client.js')).href);
const { JSDOM } = req(path.join(nmDir, 'jsdom'));

const onIslenmis = ham.replace(
  /<script(\s+[^>]*lang=["']ts["'][^>]*)>([\s\S]*?)<\/script>/g,
  (_eslesme, _oznitelikler, kod) => {
    const sonuc = ts.transpileModule(kod, {
      compilerOptions: {
        target: ts.ScriptTarget.ES2022,
        module: ts.ModuleKind.ESNext,
        verbatimModuleSyntax: true,
      },
      reportDiagnostics: true,
    });
    if (sonuc.diagnostics && sonuc.diagnostics.length > 0) {
      const mesajlar = sonuc.diagnostics
        .map((d) => ts.flattenDiagnosticMessageText(d.messageText, '\n'))
        .join('; ');
      throw new Error(`Svelte <script lang="ts"> aktarım hatası: ${mesajlar}`);
    }
    return `<script>${sonuc.outputText}</script>`;
  }
);

const derlenen = svelteCompiler.compile(onIslenmis, {
  filename: 'SayacPaneli.svelte',
  generate: 'client',
  dev: false,
  css: 'external',
});

const clientUrl = pathToFileURL(path.join(nmDir, 'svelte/src/internal/client/index.js')).href;
const discloseUrl = pathToFileURL(path.join(nmDir, 'svelte/src/internal/disclose-version.js')).href;
const calistirilabilirKod = derlenen.js.code
  .replaceAll("'svelte/internal/client'", JSON.stringify(clientUrl))
  .replaceAll('"svelte/internal/client"', JSON.stringify(clientUrl))
  .replaceAll("'svelte/internal/disclose-version'", JSON.stringify(discloseUrl))
  .replaceAll('"svelte/internal/disclose-version"', JSON.stringify(discloseUrl));

const geciciMjs = path.resolve(import.meta.dirname, `./_derlenen_SayacPaneli_${process.pid}.mjs`);
fs.writeFileSync(geciciMjs, calistirilabilirKod, 'utf8');

function etkilesimliDugmeBul(hedef, win, testId) {
  const dugme = hedef.querySelector(`button[data-testid="${testId}"]`);
  assert.ok(dugme, `Render edilen DOM içinde button[data-testid="${testId}"] bulunamadı`);
  assert.equal(dugme.isConnected, true, `${testId} düğmesi DOM ağacına bağlı değil`);
  assert.equal(dugme.disabled, false, `${testId} düğmesi devre dışı (disabled)`);
  assert.equal(dugme.hidden, false, `${testId} düğmesi gizli (hidden)`);
  assert.equal(dugme.closest('[hidden]'), null, `${testId} düğmesi gizli bir üst öğe içinde`);
  assert.notEqual(dugme.getAttribute('aria-hidden'), 'true', `${testId} düğmesi aria-hidden`);
  assert.equal(dugme.closest('[aria-hidden="true"]'), null, `${testId} düğmesi aria-hidden üst öğe içinde`);
  const stil = win.getComputedStyle(dugme);
  assert.notEqual(stil.display, 'none', `${testId} düğmesi display:none durumunda`);
  assert.notEqual(stil.visibility, 'hidden', `${testId} düğmesi visibility:hidden durumunda`);
  assert.notEqual(stil.pointerEvents, 'none', `${testId} düğmesi pointer-events:none durumunda`);
  return dugme;
}

try {
  const dom = new JSDOM('<!doctype html><html><body><div id="kok"></div></body></html>', {
    pretendToBeVisual: true,
  });
  // Derleyicinin ayırdığı bileşen CSS'si görünürlük denetimine de uygulanır.
  if (derlenen.css?.code) {
    const stil = dom.window.document.createElement('style');
    stil.textContent = derlenen.css.code;
    dom.window.document.head.append(stil);
  }
  globalThis.window = dom.window;
  globalThis.document = dom.window.document;
  globalThis.Element = dom.window.Element;
  globalThis.HTMLElement = dom.window.HTMLElement;
  globalThis.Node = dom.window.Node;
  globalThis.Text = dom.window.Text;
  globalThis.Comment = dom.window.Comment;
  globalThis.Event = dom.window.Event;
  globalThis.MouseEvent = dom.window.MouseEvent;
  globalThis.CustomEvent = dom.window.CustomEvent;
  globalThis.MutationObserver = dom.window.MutationObserver;
  globalThis.requestAnimationFrame = dom.window.requestAnimationFrame.bind(dom.window);
  globalThis.cancelAnimationFrame = dom.window.cancelAnimationFrame.bind(dom.window);

  const { default: SayacPaneli } = await import(pathToFileURL(geciciMjs).href);
  const hedef = dom.window.document.getElementById('kok');
  const ornek = svelteClient.mount(SayacPaneli, { target: hedef });
  svelteClient.flushSync();

  assert.equal(hedef.querySelector('[style]'), null, 'CSP ihlali: render edilen DOM içinde style özniteliği bulundu');

  const sayacSpan = hedef.querySelector('[data-testid="sayac-degeri"]');
  const etiketSpan = hedef.querySelector('[data-testid="secili-etiket"]');
  assert.ok(sayacSpan, 'Render edilen DOM içinde [data-testid="sayac-degeri"] bulunamadı');
  assert.ok(etiketSpan, 'Render edilen DOM içinde [data-testid="secili-etiket"] bulunamadı');

  const artirDugme = etkilesimliDugmeBul(hedef, dom.window, 'artir-dugmesi');
  const sifirlaDugme = etkilesimliDugmeBul(hedef, dom.window, 'sifirla-dugmesi');

  assert.equal(sayacSpan.textContent, '0');
  assert.equal(etiketSpan.textContent, 'Yok');

  svelteClient.flushSync(() => artirDugme.click());
  assert.equal(sayacSpan.textContent, '1');
  assert.equal(etiketSpan.textContent, 'önemli');

  svelteClient.flushSync(() => artirDugme.click());
  assert.equal(sayacSpan.textContent, '2');
  assert.equal(etiketSpan.textContent, 'önemli');

  svelteClient.flushSync(() => sifirlaDugme.click());
  assert.equal(sayacSpan.textContent, '0');
  assert.equal(etiketSpan.textContent, 'Yok');

  await svelteClient.unmount(ornek);
  console.log('K03_UI_TESTI=TAMAM');
} finally {
  fs.rmSync(geciciMjs, { force: true });
}
